#!/usr/bin/env bash
# The shell steps of the sync job in workflows/ci.yml, here so that test/sync_test.exs can run them.
# Usage: sync.sh tip | compare | close
# Needs GH_TOKEN, GITHUB_OUTPUT and GITHUB_SHA; tip needs GITHUB_REPOSITORY; compare and close need REPO;
# compare needs OUT and runs in the target checkout.
set -eo pipefail

# Same-repo PRs only: head=eyra:… leaves out PRs from forks with the same branch name,
# which gh pr close can't find by branch name.
open_prs() {
  gh api "repos/$REPO/pulls?head=eyra:mica-bff/sync&state=open" --jq length
}

beyond_header() {
  [ -n "$(git diff --cached -U0 "$1" -- "$OUT" | grep -E '^[-+]' | grep -vE '^(\+\+\+|---) ' | grep -v 'Generated by mica-bff')" ]
}

case "$1" in
  # Runs reach the sync in the order their tests finish, and a re-run keeps its old commit:
  # only the tip of main may sync, so older code never replaces newer code.
  tip)
    main=$(gh api "repos/$GITHUB_REPOSITORY/git/ref/heads/main" --jq .object.sha)
    if [ "$main" = "$GITHUB_SHA" ]; then
      echo "latest=true" >> "$GITHUB_OUTPUT"
    else
      echo "main is at $main, not $GITHUB_SHA: only the tip of main syncs."
    fi
    ;;

  # Compare with the open sync PR, or else develop.
  compare)
    git add -A
    if git fetch -q origin mica-bff/sync 2>/dev/null; then
      # A branch without an open PR (a cancelled run, a PR closed by hand) is not a sync:
      # compare with it only while its PR is open, else update so the PR opens again.
      open=$(open_prs)
      if ! beyond_header HEAD; then
        echo "close=true" >> "$GITHUB_OUTPUT"
      elif [ "$open" = 0 ] || beyond_header FETCH_HEAD; then
        echo "update=true" >> "$GITHUB_OUTPUT"
      fi
    elif beyond_header HEAD; then
      echo "update=true" >> "$GITHUB_OUTPUT"
    fi
    git reset -q
    ;;

  # Close the sync PR, or remove a branch left after a merge.
  close)
    if [ "$(open_prs)" != 0 ]; then
      gh pr close mica-bff/sync -R "$REPO" --delete-branch --comment "mica-bff@$GITHUB_SHA generates the same code as develop."
    else
      gh api -X DELETE "repos/$REPO/git/refs/heads/mica-bff/sync"
    fi
    ;;

  *)
    echo "usage: $0 tip | compare | close" >&2
    exit 2
    ;;
esac
